PN=ref('Expert Consensus: Diagnosis and Monitoring of PNH, 2026','https://onlinelibrary.wiley.com/doi/full/10.1111/ejh.70294')
PC=ref('ASH Education: When Does a PNH Clone Have Clinical Significance?','https://pmc.ncbi.nlm.nih.gov/articles/PMC8791108/')
IP=ref('US Prescribing Information: Iptacopan','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a76b5845-6e21-4d3b-ad07-cd8df1b60bee')
